import{_ as a,o as s,c as i,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"5. Expressions and Local Bindings","description":"","frontmatter":{},"headers":[],"relativePath":"spec/05-expressions.md","filePath":"spec/05-expressions.md","lastUpdated":null}'),t={name:"spec/05-expressions.md"};function o(l,e,p,r,d,c){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="_5-expressions-and-local-bindings" tabindex="-1">5. Expressions and Local Bindings <a class="header-anchor" href="#_5-expressions-and-local-bindings" aria-label="Permalink to &quot;5. Expressions and Local Bindings&quot;">​</a></h1><h2 id="_5-1-purity" tabindex="-1">5.1 Purity <a class="header-anchor" href="#_5-1-purity" aria-label="Permalink to &quot;5.1 Purity&quot;">​</a></h2><p>Ordinary <code>fn</code> and <code>op</code> bodies are pure in the initial language version. They cannot mutate parameters, buffers, files, environment variables, external state, or hidden global values.</p><p>Local <code>var</code> assignment is syntactic convenience and lowers to SSA values; it is not observable mutation outside the local function body.</p><h2 id="_5-2-let" tabindex="-1">5.2 <code>let</code> <a class="header-anchor" href="#_5-2-let" aria-label="Permalink to &quot;5.2 \`let\`&quot;">​</a></h2><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> q </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> linear</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x, q_weight)</span></span></code></pre></div><p>A <code>let</code> binding is immutable. It may carry a type annotation, which also gives contextual literals their type:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> scale: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">f32</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.5</span></span></code></pre></div><p>Tuple destructuring:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (q, k) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(q, k, positions)</span></span></code></pre></div><h2 id="_5-3-var" tabindex="-1">5.3 <code>var</code> <a class="header-anchor" href="#_5-3-var" aria-label="Permalink to &quot;5.3 \`var\`&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var x = embedding(tokens)</span></span>
<span class="line"><span>x = layer.forward(x)</span></span></code></pre></div><p>Only locals declared with <code>var</code> may be reassigned. Reassignment MUST preserve the statically inferred or declared type of the variable.</p><p>Parameters, buffers, sub-blocks, function arguments, and <code>let</code> bindings cannot be reassigned. A block&#39;s <code>state</code> members (§9.3) are assigned with the same statement; that assignment is the one observable effect in the language.</p><h2 id="_5-4-arithmetic" tabindex="-1">5.4 Arithmetic <a class="header-anchor" href="#_5-4-arithmetic" aria-label="Permalink to &quot;5.4 Arithmetic&quot;">​</a></h2><p>Supported operators:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+ - * / %</span></span>
<span class="line"><span>== != &lt; &lt;= &gt; &gt;=</span></span>
<span class="line"><span>&amp;&amp; || !</span></span>
<span class="line"><span>&amp; | ^</span></span></code></pre></div><p>Arithmetic operators are defined for compatible scalar types and are elementwise-lifted to tensors of the same dtype with valid broadcasting. Integer arithmetic wraps on overflow (two&#39;s complement) at the dtype&#39;s width; <code>/</code> and <code>%</code> on integers truncate toward zero.</p><p><code>&amp;</code>, <code>|</code>, and <code>^</code> are bitwise on integer operands and elementwise logical on boolean operands (scalars or tensors, broadcast like arithmetic); they bind looser than <code>+</code> and tighter than comparisons. The prelude functions <code>shl(x, bits)</code> and <code>shr(x, bits)</code> shift integers; <code>shr</code> is arithmetic for signed dtypes and logical for unsigned ones. On compile-time integers all five fold when both operands are constants. A contextual scalar numeric literal may be lifted across a tensor, for example <code>x * 0.5</code> when <code>x</code> has floating dtype and <code>0.5</code> is representable in that dtype. General scalar variables are not implicitly converted to a tensor of a different dtype.</p><p>Comparison of tensors produces a boolean tensor with broadcasted shape.</p><p>Logical <code>&amp;&amp;</code>, <code>||</code>, and <code>!</code> apply to scalar booleans. Elementwise boolean tensor operations are provided by library functions or explicitly specified primitive operators.</p><h2 id="_5-5-calls" tabindex="-1">5.5 Calls <a class="header-anchor" href="#_5-5-calls" aria-label="Permalink to &quot;5.5 Calls&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>linear(x, weight)</span></span>
<span class="line"><span>layer.forward(x)</span></span>
<span class="line"><span>cast&lt;f32&gt;(x)</span></span></code></pre></div><p>Generic arguments may be inferred where unambiguous. Explicit generic arguments bind generic parameters in declaration order, and the remainder are inferred.</p><p>Arguments are positional, or named with <code>name = value</code>; positional arguments come first. A parameter with a default may be omitted. An optional parameter accepts <code>none</code> or an optional value; a plain value MUST be wrapped as <code>some(value)</code>.</p><p>Every <code>where</code> constraint of the callee MUST be provable at the call site from the caller&#39;s own constraints.</p><p><code>name&lt;</code> begins a generic call only when the matching <code>&gt;</code> is immediately followed by <code>(</code>; otherwise <code>&lt;</code> is the comparison operator. Inside a generic argument list, an argument that is not a type is an arithmetic expression; comparison and logical operators there MUST be parenthesized.</p><h2 id="_5-6-if-expression" tabindex="-1">5.6 <code>if</code> expression <a class="header-anchor" href="#_5-6-if-expression" aria-label="Permalink to &quot;5.6 \`if\` expression&quot;">​</a></h2><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> y </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> causal {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        causal_mask</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(score)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        score</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span></code></pre></div><p>The condition MUST be a scalar <code>bool</code>.</p><p>Both branches MUST have the same type, including tensor shape and dtype.</p><p>Tensor-valued conditions require <code>select</code> or an equivalent elementwise operation; they are not accepted by <code>if</code>.</p><h2 id="_5-7-match" tabindex="-1">5.7 <code>match</code> <a class="header-anchor" href="#_5-7-match" aria-label="Permalink to &quot;5.7 \`match\`&quot;">​</a></h2><p>Initial <code>match</code> support is required for optional values and simple enums.</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> y </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> match</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bias {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    some</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(b) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    none</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Patterns MUST be exhaustive.</p><p>An arm pattern is a variant or binding name, <code>some(pattern)</code>, or <code>none</code>; a tuple pattern may appear only inside <code>some(...)</code>. Arms have no separator, so a tuple pattern at the start of an arm would be read as a call on the previous arm&#39;s value.</p><h2 id="_5-8-slicing-and-indexing" tabindex="-1">5.8 Slicing and indexing <a class="header-anchor" href="#_5-8-slicing-and-indexing" aria-label="Permalink to &quot;5.8 Slicing and indexing&quot;">​</a></h2><p>Value-level tensor indexing syntax includes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x[i]</span></span>
<span class="line"><span>x[b, h, s, d]</span></span>
<span class="line"><span>x[..., 0::2]</span></span>
<span class="line"><span>x[:, start:end]</span></span>
<span class="line"><span>x[:, start:end:step]</span></span></code></pre></div><p>A slice creates a logical tensor view in HIR. Backends determine whether materialization is required.</p><p>An integer index removes its axis. A slice <code>start:stop:step</code> keeps it with extent <code>max(0, (min(stop, D) - start + step - 1) / step)</code> for an axis of size <code>D</code>; <code>start</code> defaults to <code>0</code>, <code>stop</code> to <code>D</code>, and <code>step</code> to <code>1</code>. Slice bounds MUST be non-negative compile-time integers and the step a positive integer constant, so that the result shape never depends on runtime data. <code>...</code> stands for all axes not addressed explicitly and may appear once. Axes that belong to a shape pack cannot be indexed individually.</p><p>Inside index notation (section 6) every tensor access MUST index all axes, using index variables, a pack index, or integers.</p><p>Negative literal indices MAY be supported when the dimension is statically known or when the backend plan preserves well-defined indexing semantics. The initial implementation MAY reject negative indices conservatively.</p><h2 id="_5-9-shape-literals" tabindex="-1">5.9 Shape literals <a class="header-anchor" href="#_5-9-shape-literals" aria-label="Permalink to &quot;5.9 Shape literals&quot;">​</a></h2><p>A bracketed list of dimension expressions is a compile-time shape literal:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[B, S, H]</span></span>
<span class="line"><span>[H / Heads, Heads]</span></span></code></pre></div><p>Shape literals are accepted only in compile-time shape contexts and by primitives that explicitly consume a shape, such as <code>reshape</code> or <code>broadcast_to</code>. They are not runtime tensor/list values.</p><p>Example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reshape(x, [B, Heads, S, H / Heads])</span></span></code></pre></div><h2 id="_5-10-no-arbitrary-expression-statements" tabindex="-1">5.10 No arbitrary expression statements <a class="header-anchor" href="#_5-10-no-arbitrary-expression-statements" aria-label="Permalink to &quot;5.10 No arbitrary expression statements&quot;">​</a></h2><p>The initial language has no generic expression statement. Calls whose result is intentionally unused are therefore not meaningful in pure code.</p><p>This restriction keeps semicolon-free syntax unambiguous and reinforces effect-free semantics.</p>`,53)])])}const k=a(t,[["render",o]]);export{g as __pageData,k as default};
